1	import type { UiOccasion } from "@/lib/generator/types";
2	
3	/**
4	 * The predicted occasion for the user's morning.
5	 *
6	 * A prediction of their day, not a fixed rule — the seam for the future learner
7	 * is the (later, optional) `history` argument this signature can grow. For now:
8	 * the day-of-week, narrowed to occasions they actually dress for.
9	 *
10	 * Priority differs by day-type, and always falls back through the occasions the
11	 * user DID pick, so it never surfaces one they skipped. Empty picks → everyday,
12	 * matching the previous hardcoded default so nothing regresses.
13	 */
14	export function predictOccasion(now: Date, timeZone: string, occasions: string[]): UiOccasion {
15	  const weekend = isWeekend(now, timeZone);
16	  const priority: UiOccasion[] = weekend
17	    ? ["weekend", "everyday", "work", "evening"]
18	    : ["work", "everyday", "weekend", "evening"];
19	
20	  const dressesFor = new Set(occasions.map((o) => o.toLowerCase()));
21	  return priority.find((o) => dressesFor.has(o)) ?? "everyday";
22	}
23	
24	/** Day-of-week in the user's zone. `Intl` `weekday: "short"` is locale-stable in en-US. */
25	function isWeekend(now: Date, timeZone: string): boolean {
26	  let day: string;
27	  try {
28	    day = new Intl.DateTimeFormat("en-US", { timeZone, weekday: "short" }).format(now);
29	  } catch {
30	    day = new Intl.DateTimeFormat("en-US", { timeZone: "UTC", weekday: "short" }).format(now);
31	  }
32	  return day === "Sat" || day === "Sun";
33	}
34	
35	const REASONS: Record<UiOccasion, string> = {
36	  work: "Styled for your work day",
37	  everyday: "Everyday ease",
38	  weekend: "Weekend, off-duty",
39	  evening: "Out tonight",
40	};
41	
42	/** The legible "why" shown above the looks — makes the smart default feel intentional. */
43	export function defaultReason(occasion: UiOccasion): string {
44	  return REASONS[occasion];
45	}
